<template>
  <div class="page-heal-action-list">
    <CrudToolbar :title="t('heal.actions.title')" :create-text="t('heal.actions.uploadScript')" :can-create="authStore.isAdmin" @create="onUpload" />

    <el-card>
      <DataTable v-model:current-page="page" v-model:page-size="pageSize" :data="actions" :loading="loading">
        <el-table-column prop="action_id" :label="t('heal.actionId')" min-width="180" />
        <el-table-column :label="t('common.name')" min-width="160">
          <template #default="{ row }">{{ actionDisplayName(row) }}</template>
        </el-table-column>
        <el-table-column prop="action_type" :label="t('heal.actions.type')" width="120">
          <template #default="{ row }">
            <el-tag :type="row.is_builtin ? 'info' : 'warning'" size="small">
              {{ row.is_builtin ? t('heal.actions.builtin') : t('heal.actions.custom') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="risk_level" :label="t('heal.riskLevel')" width="100">
          <template #default="{ row }">
            <StatusTag :status="row.risk_level" type="default" />
          </template>
        </el-table-column>
        <el-table-column prop="is_approved" :label="t('heal.actions.approvalStatus')" width="110">
          <template #default="{ row }">
            <el-tag :type="row.is_approved ? 'success' : 'warning'" size="small">
              {{ row.is_approved ? t('common.approved') : t('common.pendingReview') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="220" fixed="right">
          <template #default="{ row }">
            <el-button
              v-if="authStore.isAdmin && !row.is_builtin && !row.is_approved"
              link
              type="success"
              size="small"
              @click="onApprove(row)"
            >
              {{ t('common.approve') }}
            </el-button>
            <ConfirmButton
              v-if="authStore.isAdmin && !row.is_builtin"
              :title="t('heal.actions.confirmDelete')"
              confirm-button-type="danger"
              @confirm="onDelete(row)"
            >
              <el-button link type="danger" size="small">{{ t('common.delete') }}</el-button>
            </ConfirmButton>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>

    <HealActionFormDialog v-model="dialogVisible" @success="loadActions" />
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage } from 'element-plus'
import { actionDisplayName } from '@/utils/actionName'
import { useAuthStore } from '@/stores/auth'
import {
  approveHealAction,
  deleteHealAction,
  getHealActions,
  type HealActionRead,
} from '@/api/healActions'
import StatusTag from '@/components/common/StatusTag.vue'
import ConfirmButton from '@/components/common/ConfirmButton.vue'
import HealActionFormDialog from './HealActionFormDialog.vue'
import DataTable from '@/components/common/DataTable.vue'
import CrudToolbar from '@/components/common/CrudToolbar.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const authStore = useAuthStore()

const actions = ref<HealActionRead[]>([])
const loading = ref(false)
const dialogVisible = ref(false)
const page = ref(1)
const pageSize = ref(10)

async function loadActions() {
  loading.value = true
  try {
    actions.value = await getHealActions()
  } catch (error) {
    showError(error, t('heal.actions.loadFailed'))
  } finally {
    loading.value = false
  }
}

function onUpload() {
  dialogVisible.value = true
}

async function onApprove(row: HealActionRead) {
  try {
    await approveHealAction(row.id)
    ElMessage.success(t('heal.actions.approveSuccess'))
    loadActions()
  } catch (error) {
    showError(error, t('common.approveFailed'))
  }
}

async function onDelete(row: HealActionRead) {
  if (row.is_builtin) {
    ElMessage.warning(t('heal.actions.builtinCannotDelete'))
    return
  }
  try {
    await deleteHealAction(row.id)
    ElMessage.success(t('heal.actions.deleted'))
    loadActions()
  } catch (error) {
    showError(error, t('common.deleteFailed'))
  }
}

onMounted(() => {
  loadActions()
})
</script>

