<template>
  <el-dialog
    v-model="visible"
    :title="t('heal.actions.uploadScript')"
    width="720px"
    :close-on-click-modal="false"
    @closed="onClosed"
  >
    <el-form ref="formRef" :model="form" :rules="rules" label-width="120px">
      <el-form-item :label="t('heal.actions.form.actionIdLabel')" prop="action_id">
        <el-input v-model="form.action_id" :placeholder="t('heal.actions.form.actionIdPlaceholder')" />
      </el-form-item>
      <el-form-item :label="t('heal.actions.form.actionNameLabel')" prop="name">
        <el-input v-model="form.name" :placeholder="t('heal.actions.form.actionNamePlaceholder')" />
      </el-form-item>
      <el-form-item :label="t('common.scriptContent')" prop="script_content">
        <CodeEditor v-model="form.script_content" :rows="10" placeholder="#!/bin/bash..." />
      </el-form-item>
      <el-form-item :label="t('heal.actions.form.paramSchema')">
        <JsonEditor
          v-model="form.parameter_schema"
          :rows="6"
          placeholder='{"type": "object", "properties": {...}}'
        />
      </el-form-item>
      <el-form-item :label="t('heal.riskLevel')" prop="risk_level">
        <el-radio-group v-model="form.risk_level">
          <el-radio value="low">{{ t('common.low') }}</el-radio>
          <el-radio value="medium">{{ t('common.medium') }}</el-radio>
          <el-radio value="high">{{ t('common.high') }}</el-radio>
        </el-radio-group>
      </el-form-item>
      <el-form-item :label="t('common.description')">
        <el-input v-model="form.description" type="textarea" :rows="3" :placeholder="t('common.optional')" />
      </el-form-item>
    </el-form>

    <template #footer>
      <el-button @click="visible = false">{{ t('common.cancel') }}</el-button>
      <el-button type="primary" :loading="submitting" @click="onSubmit">{{ t('common.submit') }}</el-button>
    </template>
  </el-dialog>
</template>

<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { createHealAction, type HealActionCreate } from '@/api/healActions'
import CodeEditor from '@/components/common/CodeEditor.vue'
import JsonEditor from '@/components/common/JsonEditor.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()

const props = defineProps<{
  modelValue: boolean
}>()

const emit = defineEmits<{
  'update:modelValue': [value: boolean]
  success: []
}>()

const visible = ref(props.modelValue)
const submitting = ref(false)
const formRef = ref<FormInstance>()
const form = ref<HealActionCreate>({
  action_id: '',
  name: '',
  description: '',
  action_type: 'custom_script',
  script_content: '',
  parameter_schema: { type: 'object', properties: {} },
  risk_level: 'medium',
})

const rules: FormRules = {
  action_id: [{ required: true, message: () => t('heal.actions.form.actionIdRequired'), trigger: 'blur' }],
  name: [{ required: true, message: () => t('heal.actions.form.actionNameRequired'), trigger: 'blur' }],
  script_content: [{ required: true, message: () => t('heal.actions.form.scriptRequired'), trigger: 'blur' }],
  risk_level: [{ required: true, message: () => t('heal.actions.form.riskRequired'), trigger: 'change' }],
}

watch(
  () => props.modelValue,
  (val) => {
    visible.value = val
  }
)

function onClosed() {
  emit('update:modelValue', false)
  formRef.value?.resetFields()
  form.value = {
    action_id: '',
    name: '',
    description: '',
    action_type: 'custom_script',
    script_content: '',
    parameter_schema: { type: 'object', properties: {} },
    risk_level: 'medium',
  }
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    await createHealAction(form.value)
    ElMessage.success(t('heal.actions.form.submitSuccess'))
    emit('success')
    visible.value = false
  } catch (error) {
    showError(error, t('heal.actions.form.uploadFailed'))
  } finally {
    submitting.value = false
  }
}
</script>
